package com.clavis.reader;
import android.app.*;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import java.io.*;import java.util.*;
final class BookDeletion {
 static void confirm(MainActivity a,Book book){new AppDialog.Builder(a).setTitle(book.title).setItems(new String[]{"Remove from library","Delete file"},(d,n)->{if(n==0)removeEntry(a,book);else confirmFiles(a,book);}).setNegativeButton("Cancel",null).show();}
 static void confirmFiles(MainActivity a,Book book){int count=BookDeletionPlan.files(book,Store.load(a)).size();new AppDialog.Builder(a).setTitle("Delete book and files?").setMessage(book.title+"\n\nPermanently delete "+count+" file(s) and remove this book from the library. Files used by another library book will be kept. Choose Remove from library to keep all files.").setPositiveButton("Delete",(d,n)->remove(a,book,null)).setNeutralButton("Remove from library",(d,n)->removeEntry(a,book)).setNegativeButton("Cancel",null).show();}
 static void remove(MainActivity a,Book book,Uri grant){PlaybackService active=PlaybackService.live;if(active!=null&&active.uri.equals(book.uri))a.stopService(new Intent(a,PlaybackService.class));ProgressDialog busy=new ProgressDialog(a);busy.setMessage("Deleting book files...");busy.setCancelable(false);busy.show();a.io.execute(()->{ArrayList<String> errors=new ArrayList<>();boolean needsAccess=false;for(String value:BookDeletionPlan.files(book,Store.load(a)))try{Uri uri=Uri.parse(value);if("file".equals(uri.getScheme())){File file=new File(uri.getPath());if(file.isDirectory())throw new IOException("Select a book file rather than a whole folder");if(file.exists()&&!file.delete())throw new SecurityException("Write access required");}else if(DocumentsContract.isDocumentUri(a,uri)){if(grant!=null)uri=DocumentsContract.buildDocumentUriUsingTree(grant,DocumentsContract.getDocumentId(uri));String mime=a.getContentResolver().getType(uri);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))throw new IOException("The selected entry points to a folder, not a book file");try{if(!DocumentsContract.deleteDocument(a.getContentResolver(),uri))throw new IOException("The provider could not delete a book file");}catch(FileNotFoundException alreadyDeleted){}}else if(a.getContentResolver().delete(uri,null,null)==0){try(InputStream ignored=a.getContentResolver().openInputStream(uri)){throw new IOException("The provider could not delete a book file");}catch(FileNotFoundException alreadyDeleted){}}}catch(SecurityException e){needsAccess=true;errors.add("Folder write access is required.");break;}catch(Exception e){errors.add(e.getMessage()==null?"A file could not be deleted":e.getMessage());}
  boolean permission=needsAccess;a.runOnUiThread(()->{if(a.isDestroyed())return;busy.dismiss();if(errors.isEmpty()){removeEntry(a,book);}else if(permission)new AppDialog.Builder(a).setTitle("Allow file deletion").setMessage("Choose the folder containing this book so Clavis can delete its files. The library entry will stay until deletion succeeds.").setPositiveButton("Choose folder",(d,n)->choose(a,book)).setNeutralButton("Remove from library",(d,n)->removeEntry(a,book)).setNegativeButton("Cancel",null).show();else new AppDialog.Builder(a).setTitle("Deletion incomplete").setMessage(String.join("\n",errors)+"\n\nThe library entry has been kept. Some files may already have been deleted; you can retry.").setNeutralButton("Remove from library",(d,n)->removeEntry(a,book)).setPositiveButton("OK",null).show();});});}
 static void removeEntry(MainActivity a,Book book){PlaybackService active=PlaybackService.live;if(active!=null&&active.uri.equals(book.uri))a.stopService(new Intent(a,PlaybackService.class));ArrayList<Book> library=Store.load(a);library.removeIf(item->item.uri.equals(book.uri));Store.save(a,library);if(a.screen.equals("Home"))a.home();else a.library(book.author);}
 static void choose(MainActivity a,Book book){a.getSharedPreferences("deletion",0).edit().putString("pending",book.uri).apply();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);Uri original=Uri.parse(book.uri);if("content".equals(original.getScheme()))intent.putExtra(DocumentsContract.EXTRA_INITIAL_URI,original);a.startActivityForResult(intent,24);}
 static void granted(MainActivity a,Intent data){try{Uri tree=data.getData();if(tree==null)return;a.getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);String pending=a.getSharedPreferences("deletion",0).getString("pending","");for(Book book:Store.load(a))if(book.uri.equals(pending)){remove(a,book,tree);return;}}catch(Exception e){new AppDialog.Builder(a).setTitle("File access").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
}
